process.env.NODE_TLS_REJECT_UNAUTHORIZED='0';
const WP='https://dev.avesa.lt';
const AUTH='Basic '+Buffer.from((process.env.WP_USER||'').trim()+':'+(process.env.WP_APP_PASS||'').trim()).toString('base64');
const GH=process.env.GH_TOKEN, REPO=process.env.GH_REPO;
const KAT='', AKC='';
const DEP=Buffer.from('','base64').toString();
async function jsonSafe(r){ const t=await r.text();
  const a=t.indexOf('['), o=t.indexOf('{');
  const i=(a>=0&&(a<o||o<0))?a:o; if(i<0) return null;
  try{ return JSON.parse(t.slice(i)); }catch(e){ return null; } }
async function putRaw(path,b64,msg){
  const url=`https://api.github.com/repos/${REPO}/contents/${path}`;
  let sha; try{ const r=await fetch(url,{headers:{Authorization:`Bearer ${GH}`}}); if(r.ok) sha=(await r.json()).sha; }catch(e){}
  const body={message:msg||'gi3', content:b64}; if(sha) body.sha=sha;
  await fetch(url,{method:'PUT',headers:{Authorization:`Bearer ${GH}`,'Content-Type':'application/json'},body:JSON.stringify(body)});
}
const putJson=(p,o)=>putRaw(p, Buffer.from(JSON.stringify(o,null,2)).toString('base64'),'gi3');
async function snip(name,code){
  const r=await fetch(`${WP}/wp-json/code-snippets/v1/snippets`,{method:'POST',
    headers:{Authorization:AUTH,'Content-Type':'application/json'},
    body:JSON.stringify({name, code, scope:'global', active:true})});
  return await jsonSafe(r)||{};
}
async function off(id){ if(!id) return; await fetch(`${WP}/wp-json/code-snippets/v1/snippets/${id}`,{method:'POST',
  headers:{Authorization:AUTH,'Content-Type':'application/json'},body:JSON.stringify({active:false})}); }
const pause=ms=>new Promise(x=>setTimeout(x,ms));
async function main(){
  const out={VERSIJA:'GI3'};
  let r=await fetch(`${WP}/wp-json/code-snippets/v1/snippets`,{headers:{Authorization:AUTH}});
  const list=await jsonSafe(r);
  for(const t of (Array.isArray(list)?list:[]).filter(s=>s.active&&/^TEMP/i.test(s.name||''))){ await off(t.id); }
  for(const [opt,val] of [['ps_uxd_kat',KAT],['ps_uxd_akc',AKC]]){
    const s=await snip('TEMP gi3 '+opt, "update_option('"+opt+"','"+val+"','no');");
    await pause(1800); await fetch(`${WP}/`,{headers:{Authorization:AUTH}}); await off(s.id);
  }
  const sd=await snip('TEMP gi3 deploy', DEP.replace(/^<\?php\s*/,''));
  await pause(2500);
  let resp=await fetch(`${WP}/?ps_gi_dep=1&k=dq7m3z`,{headers:{Authorization:AUTH}});
  out.deploy=await jsonSafe(resp);
  await pause(1500);
  /* testiniai duomenys */
  resp=await fetch(`${WP}/?ps_gi_valyti=1&k=dq7m3z`,{headers:{Authorization:AUTH}});
  out.valyta=await jsonSafe(resp);
  resp=await fetch(`${WP}/?ps_gi_test=1&k=dq7m3z`,{headers:{Authorization:AUTH}});
  out.testiniai=await jsonSafe(resp);

  const {chromium}=await import('playwright');
  const br=await chromium.launch();
  const ctx=await br.newContext({ignoreHTTPSErrors:true, viewport:{width:1680,height:1050}});
  const page=await ctx.newPage();
  const jsErr=[]; page.on('pageerror',e=>jsErr.push(String(e)));
  page.setDefaultTimeout(15000);
  const eik=async(u)=>{ try{ await page.goto(u,{waitUntil:'networkidle',timeout:45000}); return true; }catch(e){ return String(e).slice(0,60); } };

  await eik(`${WP}/?ps_uxlog2=1&k=dq7m3z`);
  await pause(3000);
  out.rail=await page.evaluate(()=>Array.prototype.map.call(
    document.querySelectorAll('.pskat-rail a'), a=>a.textContent.replace(/\s+/g,' ').trim()));
  out.eilutes=await page.evaluate(()=>{
    const t=document.querySelector('.pskat-t tbody');
    return t?Array.prototype.slice.call(t.querySelectorAll('tr')).slice(0,6)
      .map(x=>x.innerText.replace(/\n+/g,' | ').slice(0,150)):null;
  });
  out.gi_stulpelis=await page.evaluate(()=>{
    const th=Array.prototype.map.call(document.querySelectorAll('.pskat-t thead th'),x=>x.textContent.trim());
    return th;
  });
  let png=await page.screenshot(); out.s1=await putRaw('screenshots/gi3_eile.png', png.toString('base64'),'gi3');

  /* kritine eile */
  await eik(`${WP}/wp-admin/admin.php?page=ps-katalogas&kruva=visos&view=gi_kritine`);
  await pause(2000);
  out.kritine=await page.evaluate(()=>{
    const t=document.querySelector('.pskat-t tbody');
    return t?Array.prototype.slice.call(t.querySelectorAll('tr')).map(x=>x.innerText.replace(/\n+/g,' | ').slice(0,120)):null;
  });

  /* AKCIJOS: naujas taikinys */
  await eik(`${WP}/wp-admin/admin.php?page=ps-akcijos&nauja=1`);
  await pause(2000);
  out.tabai=await page.evaluate(()=>Array.prototype.map.call(document.querySelectorAll('.tb'),b=>b.textContent.trim()));
  await page.evaluate(()=>{
    const b=Array.prototype.find.call(document.querySelectorAll('.tb'),x=>x.dataset.t==='geriausia_iki');
    if(b) b.click();
    document.querySelector('.f-pav').value='Trumpos datos −25 %';
    document.querySelector('.f-reiksme').value='25';
  });
  await pause(600);
  await page.evaluate(()=>{ const b=document.querySelector('.gi-g[data-g="90"]'); if(b) b.click(); });
  await pause(400);
  await page.evaluate(()=>document.querySelector('.ak-perziureti').click());
  await pause(4500);
  out.akc_perziura=await page.evaluate(()=>{
    const s=document.querySelector('.perz-suv'), t=document.querySelector('.perz-turinys');
    return {suv:s?s.innerText.replace(/\n+/g,' | '):null,
      eiluciu:t?t.querySelectorAll('.pt tbody tr').length:0,
      pvz:t&&t.querySelector('.pt tbody tr')?t.querySelector('.pt tbody tr').innerText.replace(/\n+/g,' | ').slice(0,150):null};
  });
  png=await page.screenshot(); out.s2=await putRaw('screenshots/gi3_akcija.png', png.toString('base64'),'gi3');

  out.js_klaidos=jsErr.slice(0,8);
  await br.close(); await off(sd.id);
  r=await fetch(`${WP}/wp-json/code-snippets/v1/snippets`,{headers:{Authorization:AUTH}});
  const l2=await jsonSafe(r);
  out.liko_temp=(Array.isArray(l2)?l2:[]).filter(x=>x.active&&/^TEMP/i.test(x.name||'')).map(x=>x.name);
  await putJson('analize/gi3.json', out);
}
main().catch(async e=>{ await putJson('analize/gi3.json',{klaida:String(e).slice(0,400)}); });
